 "content": "def transform(grid):
    """Overlay the two same-sized panels around their uniform divider.

    The output keeps the shared/base color and marks positions where the two
    non-background shapes overlap with color 3.
    """
    h, w = len(grid), len(grid[0])
    # Locate the solid separator row or column.
    cut = None
    axis = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            cut, axis = r, 0
            break
    if cut is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                cut, axis = c, 1
                break
    if cut is None:
        raise ValueError('no solid separator')
    if axis == 0:
        a, b = grid[:cut], grid[cut+1:]
    else:
        a = [row[:cut] for row in grid]
        b = [row[cut+1:] for row in grid]
    if len(a) != len(b) or len(a[0]) != len(b[0]):
        raise ValueError('panels have different sizes')
    ca = {v for row in a for v in row}
    cb = {v for row in b for v in row}
    common = ca & cb
    # In these tasks the shared color is the output ground (9 in the demos,
    # and the common 7 background in the test palette).
    base = min(common) if common else 0
    out = []
    for ra, rb in zip(a, b):
        row = []
        for x, y in zip(ra, rb):
            row.append(3 if x != base and y != base else base)
        out.append(row)
    return out
